def compute(vars):
    old = vars["v2"]
    new = vars["v1"]
    if old == 0:
        return None

    value = new / old
    return {
        "value": value,
        "trace": {
            "new_2004_gains": new,
            "old_2003_gains": old,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
